const A=require('../server-data/accounts.cjs');
module.exports=async(req,res)=>{try{A.guard(req,res);if(req.method==='GET'){const who=await A.requireUser(req,res);return res.status(200).json({user:{id:who.user.id,email:who.user.email},profile:who.profile})}if(req.method!=='POST')return res.status(405).json({error:'Método no permitido.'});const b=typeof req.body==='string'?JSON.parse(req.body):req.body||{};const email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');if(['login','register','recover'].includes(b.action)&&(!email||email.length>254||!/^\S+@\S+\.\S+$/.test(email)))return res.status(400).json({error:'Ingresá un correo válido.'});if(b.action==='register'){if(password.length<8||password.length>128)return res.status(400).json({error:'Usá una contraseña de entre 8 y 128 caracteres.'});const d=await A.api('/auth/v1/signup?redirect_to='+encodeURIComponent(A.APP+'/#cuenta'),{method:'POST',service:false,body:{email,password,data:{full_name:String(b.name||'').trim().slice(0,100)}}});if(d.access_token){A.saveSession(res,d);return res.status(200).json({registered:true,confirmed:true})}return res.status(200).json({registered:true,confirmed:false,message:'Revisá tu correo y confirmá tu cuenta para ingresar.'})}if(b.action==='login'){if(!password||password.length>128)return res.status(400).json({error:'Ingresá tu contraseña.'});const d=await A.api('/auth/v1/token?grant_type=password',{method:'POST',service:false,body:{email,password}});A.saveSession(res,d);return res.status(200).json({signedIn:true})}if(b.action==='updatePassword'){if(password.length<8||password.length>128)return res.status(400).json({error:'Usá una contraseña de entre 8 y 128 caracteres.'});const who=await A.requireUser(req,res);await A.api('/auth/v1/user',{method:'PUT',service:false,token:who.access,body:{password}});return res.status(200).json({updated:true})}if(b.action==='logout'){const c=A.cookies(req);if(c.maq_access){try{await A.api('/auth/v1/logout?scope=local',{method:'POST',service:false,token:c.maq_access})}catch{}}A.setCookies(res,[A.cookie('maq_access','',0),A.cookie('maq_refresh','',0)]);return res.status(200).json({signedOut:true})}if(b.action==='recover'){await A.api('/auth/v1/recover?redirect_to='+encodeURIComponent(A.APP+'/#cuenta'),{method:'POST',service:false,body:{email}});return res.status(200).json({message:'Si existe una cuenta con ese correo, recibirás un enlace de recuperación.'})}if(b.action==='accept'){const token=String(b.access_token||''),refresh=String(b.refresh_token||'');if(token.length>5000||refresh.length>1000)return res.status(400).json({error:'Enlace inválido.'});const user=await A.api('/auth/v1/user',{service:false,token});if(!user.email_confirmed_at)return res.status(403).json({error:'Confirmá tu correo.'});A.saveSession(res,{access_token:token,refresh_token:refresh,expires_in:3600});await A.requireUser({...req,headers:{...req.headers,cookie:'maq_access='+encodeURIComponent(token)}},res);return res.status(200).json({signedIn:true})}return res.status(400).json({error:'Acción no válida.'})}catch(e){return A.error(res,e)}};
